fn encode_cyclic(s: Vec<i8>) -> Vec<i8> {
    let n = s.len();
    // L = largest multiple of 3 ≤ n
    let l = n - n % 3;
    // Prepare the output with the same length as input
    let mut result = Vec::with_capacity(n);

    // Process every full block of 3
    for i in (0..l).step_by(3) {
        // We know these indices are in bounds
        let a = *s.get(i).unwrap();
        let b = *s.get(i + 1).unwrap();
        let c = *s.get(i + 2).unwrap();
        // [a, b, c] -> [b, c, a]
        result.push(b);
        result.push(c);
        result.push(a);
    }

    // Copy over any remaining elements (0, 1 or 2 of them)
    result.extend_from_slice(&s[l..]);

    result
}

